export default [{"id": "PIA22207", "date": "31 January 2018", "text": "Curiosity took a <b>selfie</b> on Vera Rubin Ridge! Look just behind its camera mast: that's <b>Mount Sharp</b> \"photobombing\" the picture. Gale crater's rim is on the horizon.", "src": "data:image/jpeg;base64,"}, {"id": "PIA19400", "date": "15 April 2015", "text": "Curiosity's first <b>sunset in color</b> on Mars. Sunsets on Mars glow <b>blue</b>! Fine dust in the air lets blue light through near the Sun.", "src": "data:image/jpeg;base64,"}, {"id": "PIA26210", "date": "11 October 2024", "text": "A field of bright <b>sulfur stones</b>! Curiosity drove over one, cracked it open and found yellow crystals inside: the <b>first pure sulfur</b> ever found on Mars.", "src": "data:image/jpeg;base64,"}, {"id": "PIA21270", "date": "1 February 2017", "text": "A <b>dust devil</b>! A spinning whirlwind carrying dust across Gale crater on a summer afternoon. (The dark box shows where the camera zoomed in.)", "src": "data:image/jpeg;base64,"}, {"id": "PIA26519", "date": "17 January 2025", "text": "<b>Twilight clouds</b>! These \"night-shining\" clouds float very high and catch the last sunlight after sunset. (The cut corners come from a stuck camera filter.)", "src": "data:image/jpeg;base64,"}, {"id": "PIA25739", "date": "2 February 2023", "text": "<b>Sun rays on Mars!</b> Beams of light shining through clouds at sunset, the first time they were seen this clearly on Mars.", "src": "data:image/jpeg;base64,"}, {"id": "PIA21043", "date": "2016", "text": "The <b>Murray Buttes</b>: layered hills made of ancient sandstone. Long ago, wind piled up sand here, and it slowly turned into rock.", "src": "data:image/jpeg;base64,"}, {"id": "PIA16768", "date": "2013", "text": "A panorama of <b>Mount Sharp</b>. Scientists adjusted the colors to look like Earth light, so they can compare the rocks with rocks on Earth. That's why the sky looks too blue!", "src": "data:image/jpeg;base64,"}];
